import { pick } from "lodash-es";
import type * as Plotly from "plotly.js";
import { createParser, type PlotlyTemplateParser } from "./parse-from-template";

type AxisName = string;
type AxisDatum = unknown;

/**
 * A mode bar button, either a built-in button name (string) or a custom
 * button object with a name, title, icon, and click handler.
 */
export type ModeBarButton =
  | string
  | {
      name: string;
      title: string;
      icon: object;
      click: (gd: Plotly.PlotlyHTMLElement, ev: MouseEvent) => void;
    };

// Trace types that support selection via a direct click (as opposed to
// box/lasso selection, which fires plotly_selected).
const CLICK_SELECTABLE_TRACE_TYPES = new Set(["bar", "heatmap", "histogram"]);

const SCATTER_TRACE_TYPES = new Set(["scatter", "scattergl"]);

const STANDARD_POINT_KEYS: string[] = [
  "x",
  "y",
  "z",
  "lat",
  "lon",
  "curveNumber",
  "pointNumber",
  "pointNumbers",
  "pointIndex",
] as const;

// Minimal shape of the point/trace fields we access, since @types/plotly.js
// does not expose all of them (e.g. fullData, pointNumbers) on PlotDatum.
interface RawPoint {
  data?: {
    type?: string;
    mode?: string;
    hovertemplate?: string | string[];
  };
  fullData?: {
    mode?: string;
    x?: unknown[];
    y?: unknown[];
  };
  pointNumber?: number;
  pointIndex?: number;
  pointNumbers?: unknown;
  x?: unknown;
  y?: unknown;
  z?: unknown;
  curveNumber?: number;
}

function asRaw(point: Plotly.PlotDatum): RawPoint {
  return point as unknown as RawPoint;
}

/**
 * Returns true if any trace is a pure line trace: type "scatter" or
 * "scattergl" with a mode that includes "lines" but not "markers".
 */
export function hasPureLineTrace(traces: Plotly.Data[]): boolean {
  if (!traces) {
    return false;
  }
  return traces.some((trace) => {
    const type = (trace as { type?: string }).type;
    if (type !== "scatter" && type !== "scattergl") {
      return false;
    }
    const mode = (trace as { mode?: string }).mode;
    return (
      typeof mode === "string" &&
      mode.includes("lines") &&
      !mode.includes("markers")
    );
  });
}

const BOX_SELECT_ICON = {
  width: 1000,
  height: 1000,
  path: "M0 0h1000v1000H0z M100 100v800h800V100z",
};

const LASSO_SELECT_ICON = {
  width: 1031,
  height: 1000,
  path: "M1018 538c-36 207-76 331-133 456-57 124-138 250-243 250-93 0-108-58-141-58-24 0-53 22-95 22-64 0-108-46-146-118-38-72-72-172-104-282-32-110-58-224-58-224s-16-70-16-118c0-72 40-118 96-118 40 0 64 24 88 66 24 42 48 108 66 176 18 68 32 130 42 174 10 44 18 66 24 66 8 0 24-44 40-110 16-66 34-156 60-236 26-80 60-150 108-150 40 0 60 30 74 82 14 52 24 130 34 216 10 86 20 178 34 250 14 72 32 122 56 122 16 0 34-26 52-72 18-46 36-112 52-186 16-74 30-156 42-224 12-68 22-122 34-146z",
};

/**
 * Returns two mode bar buttons for enabling box/lasso selection on line
 * charts (Plotly hides these by default for line traces).
 */
export function lineSelectionButtons(
  setDragmode: (mode: string) => void,
): ModeBarButton[] {
  return [
    {
      name: "line-box-select",
      title: "Box select",
      icon: BOX_SELECT_ICON,
      click: () => setDragmode("select"),
    },
    {
      name: "line-lasso-select",
      title: "Lasso select",
      icon: LASSO_SELECT_ICON,
      click: () => setDragmode("lasso"),
    },
  ];
}

/**
 * Merges two arrays of mode bar buttons, deduplicating string buttons (first
 * occurrence wins) while always preserving custom object buttons.
 */
export function mergeModeBarButtonsToAdd(
  existing: ModeBarButton[],
  add: ModeBarButton[],
): ModeBarButton[] {
  const merged: ModeBarButton[] = [];
  const seenStrings = new Set<string>();

  for (const button of [...(existing ?? []), ...(add ?? [])]) {
    if (typeof button === "string") {
      if (seenStrings.has(button)) {
        continue;
      }
      seenStrings.add(button);
      merged.push(button);
    } else {
      // Always retain custom object buttons.
      merged.push(button);
    }
  }

  return merged;
}

/**
 * Returns true when the plot points belong to trace types that support direct
 * click selection: bar, heatmap, histogram, or scatter/scattergl without an
 * explicit mode. Returns false when all scatter/scattergl points have mode
 * set to "markers".
 */
export function shouldHandleClickSelection(
  points: Plotly.PlotDatum[],
): boolean {
  if (!points || points.length === 0) {
    return false;
  }
  return points.some((point) => {
    const raw = asRaw(point);
    const type = raw.data?.type;
    if (typeof type === "string" && CLICK_SELECTABLE_TRACE_TYPES.has(type)) {
      return true;
    }
    if (typeof type === "string" && SCATTER_TRACE_TYPES.has(type)) {
      // Scatter/scattergl without an explicit mode supports click selection.
      return raw.data?.mode == null;
    }
    return false;
  });
}

/**
 * Extracts a flat list of point indices, preferring pointIndex, then
 * pointNumber, then the values in the pointNumbers array (excluding NaN and
 * non-finite values).
 */
export function extractIndices(points: Plotly.PlotDatum[]): number[] {
  return points.flatMap((point) => {
    const raw = asRaw(point);
    if (typeof raw.pointIndex === "number") {
      return [raw.pointIndex];
    }
    if (typeof raw.pointNumber === "number") {
      return [raw.pointNumber];
    }
    if (Array.isArray(raw.pointNumbers)) {
      return raw.pointNumbers.filter(
        (n): n is number => typeof n === "number" && Number.isFinite(n),
      );
    }
    return [];
  });
}

