124	/**
125	 * Merges two arrays of mode bar buttons, deduplicating string buttons (first
126	 * occurrence wins) while always preserving custom object buttons.
127	 */
128	export function mergeModeBarButtonsToAdd(
129	  existing: ModeBarButton[],
130	  add: ModeBarButton[],
131	): ModeBarButton[] {
132	  const merged: ModeBarButton[] = [];
133	  const seenStrings = new Set<string>();
134	
135	  for (const button of [...(existing ?? []), ...(add ?? [])]) {
136	    if (typeof button === "string") {
137	      if (seenStrings.has(button)) {
138	        continue;
139	      }
140	      seenStrings.add(button);
141	      merged.push(button);
142	    } else {
143	      // Always retain custom object buttons.
144	      merged.push(button);
145	    }
146	  }
147	
148	  return merged;
149	}
