151	/**
152	 * Returns true when the plot points belong to trace types that support direct
153	 * click selection: bar, heatmap, histogram, or scatter/scattergl without an
154	 * explicit mode. Returns false when all scatter/scattergl points have mode
155	 * set to "markers".
156	 */
157	export function shouldHandleClickSelection(
158	  points: Plotly.PlotDatum[],
159	): boolean {
160	  if (!points || points.length === 0) {
161	    return false;
162	  }
163	  return points.some((point) => {
164	    const raw = asRaw(point);
165	    const type = raw.data?.type;
166	    if (typeof type === "string" && CLICK_SELECTABLE_TRACE_TYPES.has(type)) {
167	      return true;
168	    }
169	    if (typeof type === "string" && SCATTER_TRACE_TYPES.has(type)) {
170	      // Scatter/scattergl without an explicit mode supports click selection.
171	      return raw.data?.mode == null;
172	    }
173	    return false;
174	  });
175	}
